    26	    let mut max_y = path[0].1;
    27	
    28	    for point in path.iter().copied().skip(1) {
    29	        min_x = min_x.min(point.0);
    30	        min_y = min_y.min(point.1);
    31	        max_x = max_x.max(point.0);
    32	        max_y = max_y.max(point.1);
    33	    }
    34	
    35	    vec![
    36	        Point64(min_x - delta, min_y - delta),
    37	        Point64(max_x + delta, min_y - delta),
    38	        Point64(max_x + delta, max_y + delta),
    39	        Point64(min_x - delta, max_y + delta),
    40	    ]
    41	}
