    43	#[allow(non_snake_case)]
    44	pub fn InflatePaths(
    45	    paths: Paths64,
    46	    delta: f64,
    47	    join_type: JoinType,
    48	    end_type: EndType,
    49	) -> Paths64 {
    50	    match (join_type, end_type) {
    51	        (JoinType::Square, EndType::Polygon) => paths
    52	            .into_iter()
    53	            .map(|path| inflate_square_polygon(&path, delta))
    54	            .collect(),
    55	    }
    56	}
